import { IngestPipeline } from "@514labs/moose-lib";

/**
 * User Activity Event data model
 * Optimized for:
 * 1. Activity counts per user over date ranges
 * 2. Total duration per action type
 */
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

/**
 * Ingest pipeline for user activity events
 * OrderBy fields optimized for query patterns:
 * - user_id: Primary filter for user-based queries
 * - action: Secondary filter for action-based aggregations
 * - event_ts: Chronological ordering within user/action groups
 */
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["user_id", "action", "event_ts"]
  },
  stream: true,
  ingestApi: true,
});

